import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address callee, uint256 value) public {
        // Admissible domain: non-zero callee, value > 0, but callee is an EOA or contract that can receive ETH
        vm.assume(callee != address(0));
        vm.assume(callee != address(c));
        vm.assume(value > 0 && value <= address(this).balance);

        // Ensure the test contract has enough ETH to forward
        uint256 startBal = address(c).balance;
        vm.deal(address(c), value);

        // Record callee balance before forward
        uint256 calleeBefore = callee.balance;

        // Forward with empty data but value attached, so callee receives ETH if call happens
        vm.prank(address(this));
        c.forward{value: value}(callee, "");

        // After the call, the callee's balance must increase by exactly value if the call succeeded.
        // The buggy version performs no call, so callee balance remains unchanged.
        uint256 calleeAfter = callee.balance;
        assertTrue(calleeAfter == calleeBefore + value);
    }
}

